mapper.select:
SELECT ac.*, am.model_name AS modelName, aa.agent_name AS agentName, ap.prompt_title AS promptTitle FROM AI_CONVERSATION ac LEFT JOIN AI_MODEL am ON ac.model_key = am.model_key LEFT JOIN AI_AGENT aa ON ac.agent_key = aa.agent_key LEFT JOIN AI_PROMPT ap ON ac.prompt_key = ap.prompt_key WHERE 1=1
AND ac.env_code = #{req.envCode}
AND ac.memory_id = #{req.memoryKey}
AND ac.role = #{req.role}
ORDER BY ac.create_time DESC

SELECT ac.*, first_msg.content AS content, am.model_name AS modelName, aa.agent_name AS agentName, ap.prompt_title AS promptTitle FROM ( SELECT memory_key, MAX(create_time) AS max_create_time, MAX(update_time) AS max_update_time FROM AI_CONVERSATION WHERE 1=1
AND env_code = #{req.envCode}
AND memory_id = #{req.memoryKey}
GROUP BY memory_key ) group_info LEFT JOIN AI_CONVERSATION ac ON ac.memory_key = group_info.memory_key AND ac.update_time = group_info.max_update_time LEFT JOIN ( SELECT memory_key, content FROM ( SELECT memory_key, content, ROW_NUMBER() OVER (PARTITION BY memory_key ORDER BY message_order ASC) AS rn FROM AI_CONVERSATION WHERE 1=1
AND env_code = #{req.envCode}
AND memory_id = #{req.memoryKey}
) t WHERE t.rn = 1 ) first_msg ON first_msg.memory_key = group_info.memory_key LEFT JOIN AI_MODEL am ON ac.model_key = am.model_key LEFT JOIN AI_AGENT aa ON ac.agent_key = aa.agent_key LEFT JOIN AI_PROMPT ap ON ac.prompt_key = ap.prompt_key ORDER BY group_info.max_create_time DESC
